#include "stdafx.h"#include "Trans.h"#include <algorithm>#include <BmBase.h>using namespace ns_translator;bool KAaTranslator::IsVar( LPCSTR pszName ){  LPCSTR pPoint = strchr(pszName,'.');  if( pPoint )    return true;  tAliasByStrCont_::iterator itA = m_Aliases.find( pszName );  if( m_Aliases.end()!=itA )  {    return true;  }  tVarCont_::iterator it = std::find( Var.begin(), Var.end(), pszName );  if( Var.end()!=it )  {    return true;  }  if( m_pOwner )  {    bool b = m_pOwner->GetVar( pszName, NULL, NULL );    if( b )      return true;  }  return false;}int KAaTranslator::AddVar( LPCSTR pszName, KVar::eType Type ){  tAliasByStrCont_::iterator itA = m_Aliases.find( pszName );  if( m_Aliases.end()!=itA )  {    return AddVar( itA->second.refName.c_str(), Type);  }  tVarCont_::iterator it = std::find( Var.begin(), Var.end(), pszName );  if( Var.end()!=it )  {    //KTHROW( it->Type==Type );    return (int)std::distance( Var.begin(), it );  }  Var.push_back( KVar(pszName, Type) );  return (int)Var.size()-1;}